class SearchResultSerializer(DocumentSerializer):
    def to_representation(self, instance):
        doc = (
            Document.objects.select_related(
                "correspondent",
                "storage_path",
                "document_type",
                "owner",
            )
            .prefetch_related("tags", "custom_fields", "notes")
            .get(id=instance["id"])
        )
